package com.hbm.client.solarboiler;
import com.hbm.machine.solarboiler.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.client.registry.entry.EntryRegistry;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class SolarBoilerReiPlugin implements REIClientPlugin {
 private static final CategoryIdentifier<Display> TYPE=CategoryIdentifier.of("hbm","solar_boiler");
 @Override public void registerCategories(CategoryRegistry event){event.add(new Category());for(var item:java.util.List.of(SolarBoilerContent.BOILER_ITEM,SolarBoilerContent.MIRROR_ITEM))event.addWorkstations(TYPE,EntryStacks.of(item.get()));}@Override public void registerDisplays(DisplayRegistry event){event.add(new Display(SolarBoilerViews.view()));}@Override public void registerEntries(EntryRegistry event){for(var stack:SolarBoilerContent.allStacks())event.addEntry(EntryStacks.of(stack));}
 private static final class Display extends BasicDisplay {Display(SolarBoilerViews.View view){super(List.of(EntryIngredient.of(EntryStacks.of(view.input()))),List.of(EntryIngredient.of(EntryStacks.of(view.output()))));}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}}
 private static final class Category implements DisplayCategory<Display>{@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}@Override public Component getTitle(){return Component.translatable("block.hbm.machine_solar_boiler");}@Override public Renderer getIcon(){return EntryStacks.of(SolarBoilerContent.BOILER_ITEM.get());}@Override public int getDisplayWidth(Display display){return 166;}@Override public int getDisplayHeight(){return 65;}@Override public List<Widget> setupDisplay(Display display,Rectangle bounds){var widgets=new ArrayList<Widget>();widgets.add(Widgets.createDrawableWidget((g,x,y,partial)->SolarBoilerViews.draw(g,bounds.x,bounds.y)));widgets.add(Widgets.createSlot(new Point(bounds.x+30,bounds.y+24)).entries(display.getInputEntries().getFirst()).disableBackground().markInput());widgets.add(Widgets.createSlot(new Point(bounds.x+102,bounds.y+24)).entries(display.getOutputEntries().getFirst()).disableBackground().markOutput());return widgets;}}
}
